# Generate K_{5,5} and verify it's maximal triangle-free
edges = []
for u in range(5):
    for v in range(5, 10):
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print("Edges:", edges)

# Check triangle-free
def has_triangle(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[j]:
                    if k > j and k in adj[i]:
                        return True
    return False

print("Has triangle:", has_triangle(edges, 10))

# Check maximal: adding any non-edge creates a triangle
def is_maximal_triangle_free(edges, n):
    # First check triangle-free
    if has_triangle(edges, n):
        return False

    # Build adjacency
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check all non-edges
    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:
                # Try adding edge (u, v)
                # Check if this creates a triangle
                creates_triangle = False
                for w in range(n):
                    if w != u and w != v:
                        if w in adj[u] and w in adj[v]:
                            creates_triangle = True
                            break
                if not creates_triangle:
                    return False  # Not maximal
    return True

print("Is maximal triangle-free:", is_maximal_triangle_free(edges, 10))
